export const QUESTIONS = [
  { domain: "Professional Orientation & Ethics", question: "Who is considered the 'father of guidance' and established the trait-factor approach?", options: ["A) Jesse Davis", "B) E.G. Williamson", "C) Frank Parsons", "D) Carl Rogers"], correct: 2, explanation: "Frank Parsons directed the Vocation Bureau in Boston (1908) and his posthumous book 'Choosing A Vocation' (1909) established the trait-factor guidance approach. He is widely considered the father of guidance." },
  { domain: "Professional Orientation & Ethics", question: "CACREP was founded in what year to establish standards for professional competence?", options: ["A) 1990", "B) 1976", "C) 1958", "D) 1981"], correct: 3, explanation: "The Council for the Accreditation of Counseling and Related Educational Programs (CACREP) was established in 1981 to set standards for professional competence in counselor education programs." },
  { domain: "Professional Orientation & Ethics", question: "The ACA Code of Ethics requires counselors to breach confidentiality when:", options: ["A) A client requests it", "B) A family member asks for information", "C) There is clear and imminent danger to the client or others", "D) The counselor feels uncomfortable"], correct: 2, explanation: "The ACA Code of Ethics mandates breaking confidentiality when there is clear and imminent danger to the client or identifiable others (duty to warn/protect), as established by the Tarasoff case." },
  { domain: "Professional Orientation & Ethics", question: "The duty to warn, established by the Tarasoff case, requires counselors to:", options: ["A) Notify insurance companies", "B) Contact family members of all clients", "C) Report all crimes", "D) Warn identifiable potential victims of imminent danger"], correct: 3, explanation: "The Tarasoff v. Regents of the University of California case established that mental health professionals have a duty to protect identifiable potential victims when a client makes a credible threat of violence." },
  { domain: "Professional Orientation & Ethics", question: "Which Virginia milestone occurred in 1976?", options: ["A) First school counseling program", "B) First CACREP-accredited program", "C) First general practice counselor licensure law", "D) First ACA chapter"], correct: 2, explanation: "The state of Virginia passed the first general practice counselor licensure law in 1976, a landmark event in the professionalization of counseling." },
  { domain: "Professional Orientation & Ethics", question: "Accreditation applies to:", options: ["A) Programs, not individual counselors", "B) State licensing boards", "C) Insurance companies", "D) Individual counselors"], correct: 0, explanation: "Accreditation applies to programs, not individual counselors. Individual counselors are credentialed through licensure and certification." },
  { domain: "Professional Orientation & Ethics", question: "Carl Rogers published 'Counseling and Psychotherapy' in what year?", options: ["A) 1958", "B) 1942", "C) 1951", "D) 1939"], correct: 1, explanation: "Carl Rogers published 'Counseling and Psychotherapy' in 1942, which introduced his client-centered approach and was a pivotal moment in the counseling profession." },
  { domain: "Professional Orientation & Ethics", question: "The National Defense Education Act (1958) provided money for:", options: ["A) Training school counselors", "B) Research in counseling", "C) University counseling centers", "D) Community mental health centers"], correct: 0, explanation: "The National Defense Education Act of 1958 was passed to provide funding for training school counselors, largely in response to the Soviet launch of Sputnik and concerns about American education." },
  { domain: "Professional Orientation & Ethics", question: "HIPAA protects:", options: ["A) Research data only", "B) Protected health information (PHI)", "C) Counselor liability", "D) Counselor income"], correct: 1, explanation: "HIPAA (Health Insurance Portability and Accountability Act) protects protected health information (PHI), establishing national standards for the privacy and security of individually identifiable health information." },
  { domain: "Professional Orientation & Ethics", question: "Privileged communication differs from confidentiality in that it:", options: ["A) Applies only to group counseling", "B) Is broader in scope", "C) Is determined by the counselor", "D) Is a legal concept that protects clients in court proceedings"], correct: 3, explanation: "Privileged communication is a legal right (granted by state statute) that protects clients from having their confidential communications disclosed in court. Unlike confidentiality (an ethical obligation), privilege belongs to the client." },
  { domain: "Professional Orientation & Ethics", question: "Gilbert Wrenn's 1962 book 'The Counselor in a Changing World' emphasized:", options: ["A) Counseling as a profession focused on developmental needs", "B) Behavioral counseling", "C) Family therapy", "D) Psychoanalytic approaches"], correct: 0, explanation: "Gilbert Wrenn published 'The Counselor in a Changing World' in 1962, emphasizing counseling as a profession focused on developmental needs rather than solely remediation." },
  { domain: "Professional Orientation & Ethics", question: "Informed consent in counseling should include all of the following EXCEPT:", options: ["A) Limits of confidentiality", "B) Counselor's theoretical orientation", "C) Guaranteed treatment outcomes", "D) Fees and billing procedures"], correct: 2, explanation: "Informed consent should include information about limits of confidentiality, the counselor's approach, fees, and client rights. Counselors should never guarantee treatment outcomes as this is both unethical and unrealistic." },
  { domain: "Social & Cultural Diversity", question: "An 'emic' worldview refers to:", options: ["A) A universal perspective of humanity", "B) Understanding groups from their own cultural perspective", "C) A focus on similarities across cultures", "D) An autoplastic view of change"], correct: 1, explanation: "An emic worldview means understanding and helping groups from their own perspectives and culture — an insider's perspective. This contrasts with the etic view which focuses on universal similarities." },
  { domain: "Social & Cultural Diversity", question: "An 'etic' worldview focuses on:", options: ["A) Similarities across humanity — a universalism perspective", "B) Cultural differences between groups", "C) The client's family of origin", "D) An insider's perspective of culture"], correct: 0, explanation: "An etic worldview focuses on the similarities rather than differences across humanity — a universalism perspective. It emphasizes that humans are more similar than different across cultures." },
  { domain: "Social & Cultural Diversity", question: "The Racial/Cultural Identity Development Model's 'Conformity' stage is characterized by:", options: ["A) Integrating both minority and dominant cultural aspects", "B) Accepting minority views and rejecting majority", "C) Intense introspection about one's cultural identity", "D) Self-depreciation and identification with the majority"], correct: 3, explanation: "In the Conformity stage (the first stage), the individual has a self-depreciation attitude and identifies with the majority culture. This is followed by Dissonance, Resistance/Immersion, Introspection, and Integrative Awareness." },
  { domain: "Social & Cultural Diversity", question: "Acculturation refers to:", options: ["A) Adopting values, beliefs, and customs of the dominant culture while retaining some original identity", "B) Returning to one's culture of origin", "C) Rejecting the dominant culture entirely", "D) Complete absorption into the dominant group"], correct: 0, explanation: "Acculturation is the extent to which an individual of a racial or ethnic minority adopts and incorporates values, beliefs, and customs of the dominant culture. This differs from assimilation, which involves being fully absorbed into the dominant group." },
  { domain: "Social & Cultural Diversity", question: "Assimilation differs from acculturation in that:", options: ["A) Assimilation preserves the original culture", "B) Assimilation only occurs in children", "C) Assimilation is a slower process", "D) The individual is absorbed into the dominant group, losing original values"], correct: 3, explanation: "Assimilation occurs when an individual or racial/ethnic minority is absorbed into the dominant group, losing their own original values or behaviors. This is more complete than acculturation, which allows for retaining some original cultural identity." },
  { domain: "Social & Cultural Diversity", question: "Cultural encapsulation includes all EXCEPT:", options: ["A) Disregarding cultural variations", "B) Using a technique-oriented definition of counseling", "C) Developing multicultural competence", "D) Substituting model stereotypes for the real world"], correct: 2, explanation: "Cultural encapsulation (identified by Wrenn) includes substituting stereotypes for reality, disregarding cultural variations, believing in a universal truth, and using only one technique regardless of the problem. Developing multicultural competence is the antidote." },
  { domain: "Social & Cultural Diversity", question: "Stanley Strong's social influence model identifies three counselor characteristics perceived by clients:", options: ["A) Expertness, attractiveness, and trustworthiness", "B) Warmth, genuineness, and acceptance", "C) Knowledge, skills, and attitudes", "D) Empathy, congruence, and positive regard"], correct: 0, explanation: "Stanley Strong viewed counseling as an interpersonal influence process where the counselee perceives the counselor as having expertness (formal training/knowledge), attractiveness (perceived similarity), and trustworthiness (caring and desire to help)." },
  { domain: "Social & Cultural Diversity", question: "White privilege refers to:", options: ["A) Educational advantages only", "B) Advantages and entitlements that white people experience usually without awareness", "C) Earned advantages based on merit", "D) Financial advantages only"], correct: 1, explanation: "White privilege refers to advantages and entitlements that white people experience, usually without awareness. Such individuals are raised with the perception that their lives are normative, average, and ideal." },
  { domain: "Social & Cultural Diversity", question: "J. Rotter's concept of external locus of control means:", options: ["A) Belief in self-efficacy", "B) Belief that events occur independently of one's actions, determined by chance", "C) Belief that rewards are contingent on one's own actions", "D) Belief in personal agency"], correct: 1, explanation: "External locus of control is the belief that events occur independently of one's own actions and that the future is determined more by chance and luck. Internal control is the opposite — believing that rewards are contingent on one's own actions." },
  { domain: "Social & Cultural Diversity", question: "In the Racial/Cultural Identity Development Model, 'Integrative Awareness' is characterized by:", options: ["A) Self-depreciation and conformity", "B) Owning and appreciating both minority and dominant aspects of both cultures", "C) Experiencing conflict between self-appreciation and self-depreciation", "D) Rejecting the majority culture"], correct: 1, explanation: "Integrative Awareness is the final stage where the individual can own and appreciate minority and dominant aspects of both cultures. This represents the most mature level of racial/cultural identity development." },
  { domain: "Social & Cultural Diversity", question: "Proxemics is the study of:", options: ["A) Cultural food traditions", "B) Proximity as it relates to personal space, interpersonal distance, and territoriality", "C) Nonverbal facial expressions", "D) Language differences across cultures"], correct: 1, explanation: "Proxemics is the study of proximity as it relates to personal space, interpersonal distance, and territoriality. The related concept of propinquity is the tendency for people who are in close proximity to be attracted to one another." },
  { domain: "Social & Cultural Diversity", question: "Cognitive dissonance theory was developed by:", options: ["A) J. Rotter", "B) Leon Festinger", "C) Albert Bandura", "D) Stanley Strong"], correct: 1, explanation: "Leon Festinger developed the concept of cognitive dissonance — incompatibility between thoughts and actions. Dissonance is a source of motivation, and people try to reduce dissonance through denial or changing their beliefs." },
  { domain: "Social & Cultural Diversity", question: "The YAVIS acronym describes clients who tend to benefit most from traditional therapy:", options: ["A) Young, Active, Vulnerable, Insightful, Sensitive", "B) Yearning, Anxious, Verbal, Intelligent, Sincere", "C) Young, Attractive, Verbal, Intelligent, Successful", "D) Youthful, Ambitious, Vocal, Independent, Strong"], correct: 2, explanation: "YAVIS stands for Young, Attractive, Verbal, Intelligent, Successful — describing clients who tend to benefit most from traditional psychotherapy. Its counterpart QUOID (Quiet, Ugly, Old, Indigent, Dissimilar culturally) describes those less likely to benefit." },
  { domain: "Social & Cultural Diversity", question: "Ethnocentrism is the belief that:", options: ["A) Minority views should be prioritized", "B) All cultures are equally valid", "C) One's own group is the center of everything and sets the standard", "D) Cultural differences should be celebrated"], correct: 2, explanation: "Ethnocentrism is the belief that one's own group is the center of everything and that it sets the standard. This can cause intergenerational conflict when younger members begin to adopt attitudes and behaviors of other cultures." },
  { domain: "Human Growth & Development", question: "According to Erikson, the psychosocial crisis of adolescence is:", options: ["A) Trust vs. Mistrust", "B) Identity vs. Role Confusion", "C) Industry vs. Inferiority", "D) Intimacy vs. Isolation"], correct: 1, explanation: "Identity vs. Role Confusion occurs during adolescence. The individual establishes social and vocational roles and identities or is confused about adult roles." },
  { domain: "Human Growth & Development", question: "Erikson's stage of 'Generativity vs. Stagnation' occurs during:", options: ["A) Adolescence", "B) Middle adulthood", "C) Later adulthood", "D) Early adulthood"], correct: 1, explanation: "Generativity vs. Stagnation occurs in middle adulthood. Middle-aged adults desire to produce something of value and contribute to society." },
  { domain: "Human Growth & Development", question: "Piaget's preoperational stage (ages 2-7) is characterized by:", options: ["A) Abstract hypothetical thinking", "B) Egocentrism and language development", "C) Conservation and reversibility", "D) Object permanence and seeking stimulation"], correct: 1, explanation: "The preoperational stage features language development, egocentrism (inability to take in others' views), centration (focusing on one feature), and symbolic schema (using symbols in play). The child classifies objects by one feature." },
  { domain: "Human Growth & Development", question: "In Piaget's theory, 'accommodation' refers to:", options: ["A) Repeating a learned behavior", "B) Incorporating new info into existing schemas", "C) Balancing assimilation and accommodation", "D) Modifying one's cognitive structure in response to environmental events"], correct: 3, explanation: "Accommodation involves modifying the organization of the individual in response to environmental events. This contrasts with assimilation, which modifies environmental events to fit existing cognitive structures." },
  { domain: "Human Growth & Development", question: "Piaget's formal operational stage (11-15 years) is characterized by:", options: ["A) Object permanence", "B) Conservation and reversibility", "C) Abstract thinking, hypothesis testing, and logical problem solving", "D) Egocentric thinking and centration"], correct: 2, explanation: "The formal operational stage involves moving toward abstract thinking, testing hypotheses, logical problem solving, and deduction. Piaget noted that children learn best from their own actions, not lectures." },
  { domain: "Human Growth & Development", question: "Kohlberg's postconventional level includes:", options: ["A) Punishment/obedience and instrumental hedonism", "B) Good boy/nice girl and law and order", "C) Concrete operations and formal operations", "D) Social contracts and universal ethical principles"], correct: 3, explanation: "The postconventional level includes Stage 5 (social contracts — most values are relative) and Stage 6 (universal ethical principles — people develop their own moral guidelines). Stage 6 is not always reached." },
  { domain: "Human Growth & Development", question: "Freud's Oedipal complex occurs during which psychosexual stage?", options: ["A) Phallic", "B) Oral", "C) Latent", "D) Anal"], correct: 0, explanation: "The Oedipal complex occurs during the phallic stage (ages 3-5). Freud considered this the most important stage. The child realizes there is a father and must learn to share love. Resolution of the Oedipal complex leads to superego development." },
  { domain: "Human Growth & Development", question: "Vygotsky's Zone of Proximal Development (ZPD) is:", options: ["A) The physical space where learning occurs", "B) A stage of cognitive development", "C) The distance between home and school", "D) The difference between what a child can do alone vs. with help from an adult"], correct: 3, explanation: "Vygotsky's ZPD is the difference between what a kid can do on their own versus what they can do with help from an adult. Unlike Piaget, Vygotsky believed educational intervention and environment drive development, not natural stages." },
  { domain: "Human Growth & Development", question: "According to Bowlby, if no bond develops with an adult by age 3:", options: ["A) The child becomes more independent", "B) Language development will be delayed", "C) The child will have serious social issues", "D) The child will develop normally"], correct: 2, explanation: "Bowlby's attachment theory holds that a child bonds for survival. If no bond develops with an adult by age 3, the child will have serious social issues. If the bond is severed early, it is known as 'object loss' and can breed abnormal behavior." },
  { domain: "Human Growth & Development", question: "Bandura's concept of self-efficacy refers to:", options: ["A) The belief that one can perform a behavior or task", "B) Piaget's concept of equilibration", "C) Maslow's highest need", "D) One's actual ability to perform a task"], correct: 0, explanation: "Self-efficacy is the belief that we can perform some behavior or task. It is facilitated through four mechanisms: modeling, vicarious experience, receiving verbal persuasion, and paying attention to one's own physiological states." },
  { domain: "Human Growth & Development", question: "Maslow's hierarchy of needs places which need at the top?", options: ["A) Self-actualization", "B) Safety", "C) Self-esteem", "D) Belonging/love"], correct: 0, explanation: "Maslow's hierarchy from bottom to top: physiological, safety, belonging/love, self-esteem, self-actualization. Only when one need is met can you focus on the next. Most people do not achieve self-actualization." },
  { domain: "Human Growth & Development", question: "The four principal neurotransmitters discussed in counseling include all EXCEPT:", options: ["A) GABA", "B) Norepinephrine", "C) Serotonin", "D) Dopamine"], correct: 1, explanation: "The four principal neurotransmitters are acetylcholine (memory/emotional balance), serotonin (feelings/thinking/sleep), dopamine (motivation/pleasure), and GABA (reduces anxiety/promotes relaxation). Norepinephrine, while important, is not listed as one of the four principal ones in the study materials." },
  { domain: "Human Growth & Development", question: "Harlow's monkey studies demonstrated that:", options: ["A) Attachment develops only after age 1", "B) Monkeys have no attachment needs", "C) Attachment is innate; monkeys preferred cloth mothers over wire mothers with food", "D) Attachment is learned through feeding"], correct: 2, explanation: "Harlow's studies showed that attachment is an innate tendency, not learned. Monkeys preferred the terry cloth mother over the wire mother who dispensed milk, demonstrating that contact comfort, not feeding, is primary." },
  { domain: "Human Growth & Development", question: "Konrad Lorenz is associated with:", options: ["A) Imprinting and critical periods", "B) Cognitive development stages", "C) Operant conditioning", "D) Moral development"], correct: 0, explanation: "Lorenz studied imprinting — an instinctual (innate/not learned) behavior in which an infant follows the first moving object it encounters, usually the mother. He also identified critical periods where certain behaviors must be learned or they won't be learned." },
  { domain: "Human Growth & Development", question: "Carol Gilligan criticized Kohlberg's theory because:", options: ["A) It had too many stages", "B) It was not based on research", "C) It did not account for women's emphasis on caregiving and personal responsibility", "D) It focused too much on emotions"], correct: 2, explanation: "Gilligan was critical of Kohlberg because his model did not account for the notion that women place more emphasis on caregiving and personal responsibility than men, who focus on individual rights and justice. Women score lower on Kohlberg's test as a result." },
  { domain: "Human Growth & Development", question: "Daniel Levinson identified the mid-life transition as occurring at ages:", options: ["A) 40-45", "B) 45-50", "C) 30-35", "D) 35-40"], correct: 0, explanation: "Levinson identified three major transitions: early adult (17-22), mid-life (40-45), and late adult (60-65). He believed most men in his studies had mid-life crises during the mid-life transition, and that these crises are positive." },
  { domain: "Human Growth & Development", question: "William Perry's scheme for intellectual development stresses:", options: ["A) Psychosexual development", "B) Attachment theory", "C) Moral reasoning stages", "D) Dualism in teenagers and development toward relativistic thinking"], correct: 3, explanation: "Perry stresses 'dualism' common in teenagers (seeing things as black and white, right and wrong). As they mature, adults develop relativistic thinking (uncertainty is okay). The final stage is a commitment to relativism." },
  { domain: "Human Growth & Development", question: "Freud's defense mechanism of 'sublimation' involves:", options: ["A) Ascribing one's motives to others", "B) Channeling energy into socially acceptable activities", "C) Denying reality", "D) Retreating to earlier behaviors"], correct: 1, explanation: "Sublimation is a defense mechanism where energy is channeled into socially acceptable activities such as work. It is considered one of the more mature defense mechanisms." },
  { domain: "Human Growth & Development", question: "Ego dystonic means:", options: ["A) The ego is functioning well", "B) The individual finds their symptoms acceptable", "C) There is no conflict", "D) The individual perceives symptoms as undesirable"], correct: 3, explanation: "Ego dystonic means the individual perceives the symptoms or traits as undesirable. In contrast, ego syntonic means the individual perceives the symptoms or traits as acceptable." },
  { domain: "Human Growth & Development", question: "Robert Kegan's theory focuses on:", options: ["A) Group dynamics", "B) Psychosexual stages", "C) Career development stages", "D) Adult cognitive development and how people construct their own reality"], correct: 3, explanation: "Kegan focuses on adult cognitive development, particularly interpersonal relations and how people construct their own reality. He views counseling as a 'holding environment' where people can handle crises and develop new meanings." },
  { domain: "Human Growth & Development", question: "Equifinality means:", options: ["A) All disorders have the same cause", "B) Treatment outcomes are always predictable", "C) There may be multiple paths to a given outcome", "D) Disorders always have one cause"], correct: 2, explanation: "Equifinality means there may be multiple paths to a given outcome. For example, depression may be caused by physical injury, loss, or substance abuse — different causes leading to the same disorder." },
  { domain: "Career Development", question: "Donald Super's career development theory is characterized as:", options: ["A) Social learning", "B) Needs-based", "C) Life-span, life-space", "D) Actuarial"], correct: 2, explanation: "Super's theory is characterized as life-span, life-space. It views career development holistically, involving more than just the job. His life-career rainbow includes major life stages and the roles we play." },
  { domain: "Career Development", question: "Holland's RIASEC theory is classified as:", options: ["A) Actuarial/structural", "B) Needs-based", "C) Developmental", "D) Social learning"], correct: 0, explanation: "Holland's theory is actuarial or structural. It explains how personality 'types' develop and views career choice as an expression of personality. The six types form a hexagon: Realistic, Investigative, Artistic, Social, Enterprising, Conventional." },
  { domain: "Career Development", question: "In Holland's theory, 'congruence' means:", options: ["A) Adjacent personality types are similar", "B) The person has a clear picture of their goals", "C) The individual's type and environment type are the same", "D) The person has a flat profile across all six types"], correct: 2, explanation: "Congruence means the individual's personality type and the work environment type are the same. When congruence exists, job satisfaction and stability tend to be highest." },
  { domain: "Career Development", question: "Holland's concept of 'differentiation' refers to:", options: ["A) Adjacent types being psychologically similar", "B) Matching person to environment", "C) Having a clear vocational identity", "D) An individual's profile having significant highs and lows across the six types"], correct: 3, explanation: "Differentiation means an individual's profile of six types has significant highs and lows. An undifferentiated profile tends to be flat, making career decision-making more difficult." },
  { domain: "Career Development", question: "Linda Gottfredson's theory is called:", options: ["A) Learning Theory of Career Counseling", "B) Life-span, life-space", "C) Career Construction Theory", "D) Circumscription and Compromise"], correct: 3, explanation: "Gottfredson's theory is called Circumscription and Compromise. Children narrow down (circumscribe) occupations and opt out of unavailable or inappropriate (compromise) occupations as they develop." },
  { domain: "Career Development", question: "In Gottfredson's theory, orientation to sex roles occurs at ages:", options: ["A) 9-13", "B) 3-5", "C) 14+", "D) 6-8"], correct: 3, explanation: "Gottfredson's stages: Orientation to Size and Power (3-5), Orientation to Sex Roles (6-8), Orientation to Social Valuation (9-13), and Orientation to Internal Unique Self (14+). Children learn that occupations are sex-typed during ages 6-8." },
  { domain: "Career Development", question: "Krumboltz's 'planned happenstance' refers to:", options: ["A) Matching traits to job factors", "B) Carefully planning every career step", "C) Unplanned events that influence career development and should be expected", "D) Genetic factors in career choice"], correct: 2, explanation: "Planned happenstance means unplanned and chance events will influence an individual's career development, and such occurrences should be expected and taken advantage of. This is a key concept in his Learning Theory of Career Counseling." },
  { domain: "Career Development", question: "Ann Roe's career theory is based on:", options: ["A) Erikson's psychosocial stages", "B) Holland's typology", "C) Behavioral conditioning", "D) Maslow's hierarchy of needs and parent-child relations"], correct: 3, explanation: "Roe's career theory is based on Maslow's hierarchy of needs and emphasizes that genetic factors, environmental experiences, and parent-child relations influence needs structure. People raised by warm parents seek careers with interpersonal contact." },
  { domain: "Career Development", question: "Super's nine major life roles include all EXCEPT:", options: ["A) Child, student, citizen", "B) Spouse, homemaker, parent", "C) Manager, supervisor, director", "D) Worker, leisurite, pensioner"], correct: 2, explanation: "Super's nine major roles: child, student, citizen, spouse, homemaker, parent, worker, leisurite, and pensioner. These roles are played in four theaters: home, community, school, and workplace." },
  { domain: "Career Development", question: "Super's Archway Model represents:", options: ["A) The decision-making process", "B) The many determinants that comprise one's self-concept", "C) The six personality types", "D) The career rainbow only"], correct: 1, explanation: "The Archway Model is a graphic representation of the determinants comprising one's self-concept. One pillar represents individual factors (needs, interests); the other represents external factors (family, community, labor market). The self sits at the top." },
  { domain: "Career Development", question: "The trait-factor approach to career counseling involves:", options: ["A) Narrative career construction", "B) Studying the individual (traits), surveying occupations (factors), and matching them", "C) Building self-efficacy", "D) Studying unconscious motivations"], correct: 1, explanation: "Developed by Frank Parsons, the trait-factor approach involves studying the individual's traits, surveying occupations and their factors, and matching the person with an occupation using 'true reasoning.' It stimulated development of assessment techniques." },
  { domain: "Career Development", question: "Mark Savickas is associated with:", options: ["A) RIASEC typology", "B) Learning theory of career counseling", "C) Career construction theory and life design", "D) Circumscription and compromise"], correct: 2, explanation: "Savickas presented a postmodern career counseling approach based on career construction theory and the concept of life design. Individuals construct careers through identifying small stories, which are deconstructed and reconstructed with the counselor." },
  { domain: "Career Development", question: "Ginzberg's three periods of career development are:", options: ["A) Fantasy, Tentative, Realistic", "B) Growth, Exploration, Establishment", "C) Exploration, Crystallization, Specification", "D) Crystallization, Specification, Implementation"], correct: 0, explanation: "Ginzberg, Ginsburg, Axelrad & Herma identified three periods: Fantasy (birth-11), Tentative (11-17, with stages of interest, capacity, value, and transition), and Realistic (17+, with stages of exploration, crystallization, and specification)." },
  { domain: "Career Development", question: "The Dictionary of Occupational Titles (DOT) contains approximately how many job definitions?", options: ["A) 1,000", "B) 5,000", "C) 20,000", "D) 12,000"], correct: 3, explanation: "The Dictionary of Occupational Titles, a US Department of Labor document, defines approximately 12,000 different jobs with occupational descriptions including duties, tasks, and tools used." },
  { domain: "Career Development", question: "The difference between 'undecided' and 'indecisive' in career counseling is:", options: ["A) Indecisive individuals need more info; undecided have trouble deciding", "B) Both terms refer to lack of motivation", "C) Undecided individuals need more info; indecisive individuals have trouble deciding even with info", "D) There is no difference"], correct: 2, explanation: "Undecided implies the individual needs more information and then can or will make a decision. Indecisiveness implies that even with more information, the individual has problems making a decision." },
  { domain: "Career Development", question: "Tiedman and Miller-Tiedman's career decision-making model parallels:", options: ["A) Maslow's hierarchy", "B) Erikson's psychosocial development", "C) Piaget's cognitive development", "D) Kohlberg's moral development"], correct: 1, explanation: "Tiedman and Miller-Tiedman believed career development occurred as part of cognitive development as one resolved ego-relevant crises, paralleling Erikson's psychosocial development model." },
  { domain: "Helping Relationships", question: "Carl Rogers identified which three core conditions for therapeutic change?", options: ["A) Empathy, respect (unconditional positive regard), and genuineness (congruence)", "B) Attending, inquiry, reflection", "C) Expertness, attractiveness, trustworthiness", "D) Interpretation, free association, transference"], correct: 0, explanation: "Rogers' human relations core consists of empathy, respect (unconditional positive regard), and genuineness (congruence). These are considered the necessary and sufficient conditions for therapeutic personality change." },
  { domain: "Helping Relationships", question: "Allen Ivey is associated with:", options: ["A) Psychoanalytic theory", "B) Reality therapy", "C) Communication skills core — attending, inquiry, and reflection", "D) Social influence core"], correct: 2, explanation: "Allen Ivey identified the skills core of counseling — communication skills such as attending, inquiry, and reflection. These microskills are foundational to effective counseling across theoretical orientations." },
  { domain: "Helping Relationships", question: "In psychoanalytic therapy, transference refers to:", options: ["A) The counselor projecting onto the client", "B) Channeling energy into work", "C) Redirecting emotions to a safer target", "D) Projections onto the therapist that must be worked through"], correct: 3, explanation: "Transference is the client's projection of feelings and attitudes onto the therapist, often from earlier relationships. These projections must be worked through in therapy. Countertransference is the opposite — the therapist's projections onto the client." },
  { domain: "Helping Relationships", question: "In Freud's dream analysis, 'latent content' refers to:", options: ["A) What you remember from the dream", "B) The emotional response to the dream", "C) Recurring dream themes", "D) The hidden, unconscious meaning of the dream"], correct: 3, explanation: "Latent content represents the hidden, unconscious representations in a dream. Manifest content is what you actually remember happening in the dream. The goal of dream interpretation is to uncover the latent content." },
  { domain: "Helping Relationships", question: "Karen Horney believed the core of all neuroses is:", options: ["A) Biological instincts", "B) Unresolved Oedipal conflicts", "C) Cognitive distortions", "D) Problematic human relations emanating from the environment"], correct: 3, explanation: "Horney, a neo-Freudian, believed the core of all neuroses are problematic human relations that emanate from the environment (not intrapsychic issues). Security is each person's major motivation, and anxiety results when it is not achieved." },
  { domain: "Helping Relationships", question: "Virginia Satir identified that under stress, families adopt communication styles including all EXCEPT:", options: ["A) Differentiator", "B) Blamer", "C) Placater", "D) Super reasonable"], correct: 0, explanation: "Satir identified five styles under stress: placater, blamer, super reasonable, irrelevant, and congruent communicator. Her humanistic approach emphasized that families have resources within themselves to flourish." },
  { domain: "Helping Relationships", question: "Murray Bowen's family systems theory emphasizes:", options: ["A) Miracle questions", "B) Structural boundaries and subsystems", "C) Differentiation of self, triangles, and multigenerational transmission", "D) Empty chair technique"], correct: 2, explanation: "Bowen's theory includes eight concepts: differentiation of self, triangles, nuclear family emotional system, family projection process, emotional cutoff, multigenerational transmission, sibling position, and societal regression. The genogram is a key assessment tool." },
  { domain: "Helping Relationships", question: "Salvador Minuchin developed:", options: ["A) Structural family therapy", "B) Bowen family systems", "C) Narrative family therapy", "D) Experiential family therapy"], correct: 0, explanation: "Minuchin developed structural family therapy, which focuses on family organization, transactional patterns, subsystems (spousal, parenting, sibling), and boundaries (permeable/diffuse or rigid). Diffuse boundaries lead to enmeshment; rigid boundaries lead to disengagement." },
  { domain: "Helping Relationships", question: "In solution-focused brief therapy, the 'miracle question' is designed to:", options: ["A) Explore family of origin issues", "B) Analyze past traumas", "C) Help clients envision what life would look like without their problem", "D) Identify cognitive distortions"], correct: 2, explanation: "The miracle question (de Shazer and Berg) asks clients to imagine waking up and their problem being solved — what would be different? This helps clients envision solutions and identify exceptions to the problem pattern." },
  { domain: "Helping Relationships", question: "The 'identified patient' in family therapy refers to:", options: ["A) The family member with the presenting symptoms", "B) The therapist", "C) The family member who initiated therapy", "D) The most differentiated family member"], correct: 0, explanation: "The identified patient (IP) is the family member with the presenting symptoms. Family therapy views pathology not within the individual but within the social context — ordinarily the family." },
  { domain: "Helping Relationships", question: "Joining in family therapy refers to:", options: ["A) Entering the family system by engaging its members to explore and modify dysfunction", "B) Having the family join a support group", "C) Adding a co-therapist", "D) Connecting two family subsystems"], correct: 0, explanation: "Joining is a therapeutic tactic of entering a family system by engaging its separate members and subsystems, gaining access to explore and ultimately modify dysfunctional aspects of the system." },
  { domain: "Helping Relationships", question: "Narrative therapy's technique of 'externalization' involves:", options: ["A) Acting out emotions physically", "B) Transferring blame to others", "C) Expressing anger outwardly", "D) Separating the problem from the person"], correct: 3, explanation: "Externalization in narrative therapy (White and Epston) separates the problem from the person, allowing clients to examine and 're-author' their stories. It empowers clients by making the problem, not the person, the focus." },
  { domain: "Helping Relationships", question: "Glasser's Reality Therapy is based on:", options: ["A) Existential philosophy", "B) Choice theory and five basic needs", "C) Psychoanalytic theory", "D) Classical conditioning"], correct: 1, explanation: "Reality therapy is based on Glasser's choice theory, which posits that all behavior is chosen to satisfy five basic needs: survival, love/belonging, power, freedom, and fun. The WDEP system guides the therapeutic process." },
  { domain: "Helping Relationships", question: "Enmeshment in family therapy refers to:", options: ["A) Family members who are emotionally cut off", "B) Clear, healthy boundaries", "C) A strong therapeutic alliance", "D) Boundaries are blurred and members are overconcerned with each other's lives"], correct: 3, explanation: "Enmeshment occurs when boundaries between family members are blurred and members are overconcerned and overinvolved in each other's lives, limiting individual autonomy. It is contrasted with disengagement (rigid boundaries)." },
  { domain: "Helping Relationships", question: "Nathan Ackerman's psychodynamic family therapy emphasizes:", options: ["A) Structural boundaries", "B) Behavioral parent-skills training", "C) Cognitive restructuring", "D) Psychological heritage from families of origin and homeostasis"], correct: 3, explanation: "Ackerman held that in a new marriage, couples bring psychological heritage from families of origin, including introjects (imprints/memories) from parents. The family unit seeks homeostasis, and individual pathology disturbs this." },
  { domain: "Group Counseling", question: "Whose work has been classified as a preface to the group movement?", options: ["A) Sigmund Freud", "B) Carl Rogers", "C) Alfred Adler", "D) B.F. Skinner"], correct: 2, explanation: "Adler's work has been classified as a preface to the group movement, with his emphasis on social participation, belonging, and family structure/birth order." },
  { domain: "Group Counseling", question: "A psychoeducational group focuses on:", options: ["A) Improving interpersonal skills through process examination", "B) Acquiring information and skill building", "C) Personality reconstruction", "D) Support without professional leadership"], correct: 1, explanation: "Psychoeducational groups focus on acquiring information and skill building. They can be preventative, growth-oriented, or remedial, and are found in social service agencies, mental health settings, and universities." },
  { domain: "Group Counseling", question: "The difference between a counseling group and a psychotherapy group is:", options: ["A) Psychotherapy groups are always shorter", "B) Counseling groups are always larger", "C) Counseling groups focus on growth and prevention; psychotherapy groups focus on remediation and personality reconstruction", "D) They are exactly the same"], correct: 2, explanation: "Counseling groups focus on growth, development, and prevention. Psychotherapy groups focus on remediation, treatment, and personality reconstruction. Psychotherapy groups may run longer and are found in mental health agencies, clinics, and hospitals." },
  { domain: "Group Counseling", question: "A T-Group (training group) focuses on:", options: ["A) Task completion", "B) Psychoeducation", "C) Improving interpersonal skills — how one functions within a group", "D) Self-help and mutual support"], correct: 2, explanation: "T-Groups (training groups) focus on improving interpersonal skills. How one functions within a group is examined, making it a process-oriented experience." },
  { domain: "Group Counseling", question: "Self-help groups differ from counseling groups in that they:", options: ["A) Focus on personality reconstruction", "B) Are always professionally led", "C) Are usually not professionally led and focus on support", "D) Use standardized curricula"], correct: 2, explanation: "Self-help groups are support systems that help with psychological stress. They are usually not professionally led and focus on issues such as weight control, survivors of trauma, and parents who have lost a child." },
  { domain: "Group Counseling", question: "Advantages of group counseling include all EXCEPT:", options: ["A) Members can play a variety of roles", "B) Complete confidentiality is guaranteed", "C) People learn in a social context", "D) It replicates participants' everyday world"], correct: 1, explanation: "Advantages include social learning, peer confrontation, practicing new skills, and cost-effectiveness. However, confidentiality cannot be guaranteed in groups because group members may share information outside the group." },
  { domain: "Group Counseling", question: "Group dynamics refers to:", options: ["A) The counselor's leadership style only", "B) The number of members in a group", "C) The physical arrangement of members", "D) The development and interaction of forces inherent in group interaction"], correct: 3, explanation: "Group dynamics refers to the development and interaction of the forces inherent in group interaction. It encompasses all the complex processes that occur when people come together in a group setting." },
  { domain: "Group Counseling", question: "Task/work groups are characterized by:", options: ["A) Personality reconstruction", "B) Focus on emotional catharsis", "C) Teams operating independently sharing one or more goals", "D) Always being led by a therapist"], correct: 2, explanation: "Task/work groups consist of teams of people operating independently and sharing one or more goals. Examples include committees, planning groups, and study groups." },
  { domain: "Assessment & Testing", question: "The normal curve distributes scores so that one standard deviation encompasses:", options: ["A) 99% of scores", "B) 68% of scores", "C) 50% of scores", "D) 95% of scores"], correct: 1, explanation: "One SD = 68% (34% above mean, 34% below). Two SDs = 95%. Three SDs = 99%. The normal curve distributes scores into six equal parts — three above and three below the mean." },
  { domain: "Assessment & Testing", question: "A Z-score has a mean of ___ and a standard deviation of ___:", options: ["A) 100, 15", "B) 50, 10", "C) 0, 1", "D) 100, 16"], correct: 2, explanation: "A Z-score has a mean of 0 and a standard deviation of 1. A T-score has a mean of 50 and SD of 10 (transformed to eliminate negative scores)." },
  { domain: "Assessment & Testing", question: "Test-retest reliability involves:", options: ["A) Calculating internal consistency", "B) Using alternate forms of the same test", "C) Administering the same test twice to the same group and correlating results", "D) Dividing a test in half and correlating the halves"], correct: 2, explanation: "Test-retest reliability involves administering the same instrument to the same group twice and correlating the results. Other types include equivalence (alternate forms), split-half, and inter-item reliability." },
  { domain: "Assessment & Testing", question: "Construct validity is established when:", options: ["A) The test predicts future behavior", "B) The test appears to be valid on its face", "C) The test measures the hypothetical construct it claims to measure", "D) The test items are drawn from the relevant domain"], correct: 2, explanation: "Construct validity means a test measures the hypothetical construct it claims to measure. It includes convergent validity (high correlation with related constructs) and discriminant validity (no significant correlation with unrelated constructs)." },
  { domain: "Assessment & Testing", question: "Predictive validity refers to:", options: ["A) Whether test predictions are confirmed by later behavior", "B) How the test looks to test-takers", "C) Whether test items represent the content domain", "D) Correlation with other tests given at the same time"], correct: 0, explanation: "Predictive validity means the predictions made by the test are confirmed by later behavior. Concurrent validity compares results with other tests or behaviors at approximately the same time." },
  { domain: "Assessment & Testing", question: "A positively skewed distribution has:", options: ["A) A perfectly symmetrical shape", "B) Equal mean, median, and mode", "C) The left tail longer; scores concentrated on the right", "D) The right tail longer; scores concentrated on the left"], correct: 3, explanation: "In a positive skew, the right tail is longer and the mass of the distribution is concentrated on the left. In a negative skew, the left tail is longer with scores concentrated on the right." },
  { domain: "Assessment & Testing", question: "The difficulty index of 0.25 means:", options: ["A) The item is very easy", "B) 25% of people answered the item correctly", "C) The item discriminates well", "D) The item has high reliability"], correct: 1, explanation: "The difficulty index indicates the percentage of people who answered an item correctly. Higher numbers mean easier items. 0.25 means only 25% answered correctly — a relatively difficult item." },
  { domain: "Assessment & Testing", question: "A correlation coefficient:", options: ["A) Ranges from -1 to +1", "B) Can only be positive", "C) Ranges from 0 to 1", "D) Determines causation"], correct: 0, explanation: "A correlation coefficient (r) ranges from -1 to +1. It shows a relationship between two sets of numbers but cannot determine a causal relationship. Bivariate = correlation between 2 variables; multivariate = multiple variables." },
  { domain: "Assessment & Testing", question: "The Wechsler intelligence scales have a mean of ___ and SD of ___:", options: ["A) 50, 10", "B) 100, 15", "C) 100, 16", "D) 0, 1"], correct: 1, explanation: "The Wechsler scales have a mean of 100 and SD of 15. The Stanford-Binet has a mean of 100 and SD of 16. Wechsler created his own IQ test with performance skills because he felt the Binet was more focused on verbal skills." },
  { domain: "Assessment & Testing", question: "The Stanford-Binet IQ test was originally created to:", options: ["A) Measure adult intelligence", "B) Evaluate personality traits", "C) Assess career aptitude", "D) Discriminate normal from intellectually disabled Parisian children"], correct: 3, explanation: "The Stanford-Binet was created in 1905 to discriminate normal from intellectually disabled Parisian children. It was later Americanized by Terman. The old formula was MA/CA × 100, now replaced by the Standard Age Score." },
  { domain: "Assessment & Testing", question: "Projective tests are characterized by:", options: ["A) Likert scale ratings", "B) True/false items only", "C) Showing neutral stimuli where clients project personality using the unconscious", "D) Forced-choice multiple-choice items"], correct: 2, explanation: "Projective tests show neutral stimuli and the client projects their personality on an unstructured task using the unconscious mind. Types include association (Rorschach), completion (sentence completion), and construction (drawing)." },
  { domain: "Assessment & Testing", question: "Criterion-referenced tests compare:", options: ["A) An individual to others who took the test (norms)", "B) Two different test forms", "C) An individual's performance to a predetermined criterion or standard", "D) Results within the individual across subtests"], correct: 2, explanation: "Criterion-referenced tests compare an individual's performance to some predetermined criterion. Norm-referenced tests compare individuals to others. Ipsative interpretation compares results within the individual." },
  { domain: "Assessment & Testing", question: "The coefficient of determination is calculated by:", options: ["A) Squaring the correlation coefficient", "B) Taking the square root of the correlation", "C) Dividing two correlation coefficients", "D) Adding two correlations together"], correct: 0, explanation: "The coefficient of determination is the correlation coefficient squared. For example, squaring a correlation of .9 yields .81 (81% common/shared variance). The remaining 19% is the coefficient of nondetermination (error/unique variance)." },
  { domain: "Assessment & Testing", question: "Regression toward the mean predicts that:", options: ["A) Extreme pre-test scores will likely move closer to the mean on posttest", "B) Reliability always increases", "C) All scores will become identical", "D) The mean will shift upward over time"], correct: 0, explanation: "If someone earns a very low or very high score on a pre-test, they will likely score closer to the mean on the posttest. This is due to error from chance, personal, and environmental factors that will be different at retest." },
  { domain: "Assessment & Testing", question: "A stanine converts scores into how many parts?", options: ["A) 9", "B) 10", "C) 7", "D) 5"], correct: 0, explanation: "A stanine converts a distribution of scores into nine parts, with 5 in the middle and a standard deviation of about 2. It is a commonly used standardized score format." },
  { domain: "Research & Program Evaluation", question: "A Type I error (Alpha) occurs when:", options: ["A) Your sample is too large", "B) You fail to reject a true null hypothesis", "C) You reject the null hypothesis when it is actually correct (false positive)", "D) You accept the alternative hypothesis correctly"], correct: 2, explanation: "Type I error is rejecting the null hypothesis (which states no difference) when it is actually correct — saying there is a significant difference when there isn't one. As the significance level decreases (.05 to .01), Type I error decreases but Type II increases." },
  { domain: "Research & Program Evaluation", question: "A Type II error (Beta) occurs when:", options: ["A) Your sample is too small", "B) You reject the null hypothesis in error", "C) You fail to reject the null hypothesis when there actually is a difference", "D) Your significance level is too high"], correct: 2, explanation: "Type II error is failing to reject the null hypothesis when there is a real difference between variables — accepting 'no difference' when a difference actually exists. Larger sample sizes reduce risk of both Type I and Type II errors." },
  { domain: "Research & Program Evaluation", question: "The Hawthorne effect refers to:", options: ["A) Changes in performance because subjects know they are being observed", "B) The placebo effect", "C) Researcher bias influencing results", "D) Regression toward the mean"], correct: 0, explanation: "The Hawthorne effect occurs when subjects' performance is influenced simply by receiving attention or knowing they are participating in research. It is a threat to external validity." },
  { domain: "Research & Program Evaluation", question: "Internal validity is threatened by all EXCEPT:", options: ["A) Maturation of subjects", "B) Instrumentation changes", "C) Having a large sample size", "D) Subject attrition/mortality"], correct: 2, explanation: "Threats to internal validity include selection bias, instrumentation changes, maturation, mortality/attrition, experimenter bias, history, and statistical regression. A large sample size actually helps reduce errors and improve validity." },
  { domain: "Research & Program Evaluation", question: "A quasi-experiment differs from a true experiment in that:", options: ["A) It uses qualitative data only", "B) Random assignment to groups is not possible", "C) It has no independent variable", "D) It has no dependent variable"], correct: 1, explanation: "In a quasi-experiment, randomization of subjects to treatment and control groups is not possible, or no control/comparison group is available. True experiments have random assignment and manipulation of the independent variable." },
  { domain: "Research & Program Evaluation", question: "Nominal level data involves:", options: ["A) Equal intervals between items", "B) A true zero point", "C) Hierarchical ordering with equal intervals", "D) Data classified in categories where numbers have no mathematical meaning"], correct: 3, explanation: "Nominal data is classified in terms of categories (e.g., gender, religion). Numbers have no mathematical meaning or order. This is the most basic level of measurement." },
  { domain: "Research & Program Evaluation", question: "Ratio level data differs from interval data because ratio data has:", options: ["A) Only categorical information", "B) Unequal intervals", "C) No mathematical meaning", "D) A true zero point"], correct: 3, explanation: "Ratio data has all properties of interval data (hierarchical ordering, equal intervals) plus a true zero point. Examples: weight, number of siblings, wages. Statistical analyses are most powerful with ratio-level data." },
  { domain: "Research & Program Evaluation", question: "ANOVA is used instead of a t-test when:", options: ["A) There are 3 or more groups", "B) The sample is very small", "C) There are exactly 2 groups", "D) Data is nominal"], correct: 0, explanation: "A t-test determines if means of two groups differ significantly. ANOVA (one-way) is used when there is one variable at three or more levels. Factorial ANOVA handles two or more independent variables simultaneously." },
  { domain: "Research & Program Evaluation", question: "Chi-square is a non-parametric test used when:", options: ["A) You have nominal (categorical) data", "B) Data is ratio level", "C) You want to determine causation", "D) The distribution is perfectly normal"], correct: 0, explanation: "Chi-square is a non-parametric test used with nominal data to determine whether two distributions differ significantly. Non-parametric tests are used when you cannot assume a normal distribution." },
  { domain: "Research & Program Evaluation", question: "Formative evaluation is:", options: ["A) A summary evaluation at the end of a program", "B) A one-time assessment", "C) An ongoing process evaluation to measure effectiveness of a technique", "D) Only used in research settings"], correct: 2, explanation: "Formative evaluation is ongoing, measuring how well a new technique or part of a program works during implementation. Summative evaluation is a summary evaluation at the end of a cycle to see how well goals have been met." },
  { domain: "Research & Program Evaluation", question: "The significance level of .05 means:", options: ["A) You accept 5 chances in 100 of rejecting the null hypothesis in error", "B) Results are 95% likely to be wrong", "C) The sample size must be at least 5%", "D) 5% of the data is unreliable"], correct: 0, explanation: "At .05 significance level, you are willing to accept the possibility of rejecting the null hypothesis in error 5 times out of 100. Lower significance levels (.01, .001) reduce Type I error but increase Type II error." },
  { domain: "Research & Program Evaluation", question: "The Rosenthal effect (experimenter bias) refers to:", options: ["A) The placebo effect", "B) Changes in subject behavior brought on by researcher expectations", "C) Subjects changing behavior because they know they're being studied", "D) Statistical regression toward the mean"], correct: 1, explanation: "The Rosenthal effect (experimenter bias) refers to changes in subjects' behavior brought on by researcher expectations, behaviors, or attitudes. It is related to the self-fulfilling prophecy (Pygmalion effect)." },
  { domain: "Research & Program Evaluation", question: "Qualitative research differs from quantitative in that it:", options: ["A) Assumes multiple realities socially constructed by individuals and groups", "B) Always uses large samples", "C) Assumes a single objective reality", "D) Uses only statistical methods"], correct: 0, explanation: "Qualitative research assumes multiple realities socially constructed by individuals and groups. It tends to study individual units in naturalistic settings, and researchers may be the primary instrument for data collection." },
  { domain: "Research & Program Evaluation", question: "Action research is:", options: ["A) Only used in laboratory settings", "B) Pure experimental research", "C) Conducted to improve services or a program, having an evaluative function", "D) Always longitudinal"], correct: 2, explanation: "Action research is conducted in an attempt to improve services or a program, having an evaluative function. It is practical and applied, often used by practitioners to evaluate and improve their own work." },
  { domain: "Research & Program Evaluation", question: "Stratified sampling means:", options: ["A) Selecting the most convenient participants", "B) Randomly selecting any individuals", "C) Ensuring major subgroups in the population are sampled", "D) Using only volunteers"], correct: 2, explanation: "Stratified sampling ensures that major subgroups in the population will be sampled. Proportional stratified sampling randomly selects the same proportion of individuals for the sample as they represent in the population." },
  { domain: "Research & Program Evaluation", question: "Solomon Four-Group Design is used to:", options: ["A) Compare four different treatments", "B) Use four different measurement instruments", "C) Examine the effect of any pretest on the experimental treatment", "D) Test four hypotheses simultaneously"], correct: 2, explanation: "The Solomon Four-Group Design examines the effect of any pretest used on the experimental treatment. It controls for testing effects by having some groups take the pretest and others not." },
  { domain: "Research & Program Evaluation", question: "Ex post facto research is:", options: ["A) Causal-comparative research studying relationships after the fact", "B) A true experiment", "C) Always qualitative", "D) Only used with animals"], correct: 0, explanation: "Ex post facto (causal-comparative) research studies possible causal relationships among variables after the fact. Since the events have already occurred, the researcher cannot manipulate the independent variable." },
  { domain: "Research & Program Evaluation", question: "ANCOVA is used to:", options: ["A) Analyze qualitative data", "B) Replace all other statistical tests", "C) Compare nominal data", "D) Control the influence of one or more independent variables on the dependent variable"], correct: 3, explanation: "ANCOVA (Analysis of Covariance) controls the influence of one or more independent variables on the dependent variable using a covariate. The covariate accounts for systematic differences (e.g., pre-test scores), and then ANOVA is conducted on adjusted scores." },
  { domain: "Research & Program Evaluation", question: "Meta-analysis is:", options: ["A) A single large study", "B) A type of case study", "C) A qualitative interview method", "D) Research comparing findings across multiple studies"], correct: 3, explanation: "Meta-analysis is research that compares findings across multiple studies on the same topic, providing a statistical synthesis of research results to identify overall trends and effect sizes." },
  { domain: "Research & Program Evaluation", question: "Ecological validity refers to:", options: ["A) Whether the study uses environmental variables", "B) Whether the study is conducted outdoors", "C) Whether results can be generalized from one setting to another", "D) Whether animals were used"], correct: 2, explanation: "Ecological validity is a type of external validity asking whether results can be generalized from one setting or circumstance to another. It is a confound to external validity." },
  { domain: "Professional Orientation & Ethics", question: "The American Personnel and Guidance Association was founded in:", options: ["A) 1962", "B) 1951", "C) 1958", "D) 1942"], correct: 1, explanation: "The American Personnel and Guidance Association was founded in 1951. It later became the ACA." },
  { domain: "Professional Orientation & Ethics", question: "Jesse Davis is significant because he:", options: ["A) Began working as a counselor in a Detroit high school in 1898", "B) Created the Strong Interest Inventory", "C) Founded CACREP", "D) Published the first counseling textbook"], correct: 0, explanation: "Jesse Davis began working as a counselor in a Detroit high school in 1898, one of the earliest school counselors." },
  { domain: "Professional Orientation & Ethics", question: "E.G. Williamson modified Parsons' approach in:", options: ["A) The Counselor in a Changing World", "B) Choosing A Vocation", "C) Counseling and Psychotherapy", "D) How to Counsel Students (1939)"], correct: 3, explanation: "E.G. Williamson published 'How to Counsel Students' in 1939, modifying Parsons' trait-factor approach into a more clinical, directive method." },
  { domain: "Professional Orientation & Ethics", question: "The Strong Vocational Interest Blank was published in:", options: ["A) 1909", "B) 1939", "C) 1927", "D) 1917"], correct: 2, explanation: "Published in 1927, it later evolved into the Strong Interest Inventory." },
  { domain: "Professional Orientation & Ethics", question: "The Smith-Hughes Act (1917) provided:", options: ["A) Federal funds for vocational education and guidance", "B) Counselor licensure funding", "C) Psychoanalytic training funds", "D) University counseling grants"], correct: 0, explanation: "The Smith-Hughes Act granted federal funds for vocational education and guidance, one of the first federal supports for the counseling profession." },
  { domain: "Professional Orientation & Ethics", question: "A dual relationship in counseling means:", options: ["A) Seeing two clients simultaneously", "B) Using two therapeutic approaches", "C) Co-leading a group", "D) Having a secondary role with a client beyond the professional relationship"], correct: 3, explanation: "A dual relationship occurs when a counselor has a secondary role (social, business, sexual) with a client beyond the professional relationship. The ACA Code of Ethics addresses these." },
  { domain: "Professional Orientation & Ethics", question: "The National Vocational Guidance Association was founded in:", options: ["A) 1942", "B) 1913", "C) 1927", "D) 1908"], correct: 1, explanation: "Founded in 1913, it was the first professional counseling association in the United States." },
  { domain: "Social & Cultural Diversity", question: "The 'Resistance and Immersion' stage is characterized by:", options: ["A) Integrating both cultures", "B) Accepting minority views and rejecting majority views", "C) Conformity to the majority", "D) Self-depreciation"], correct: 1, explanation: "In Resistance and Immersion, the individual accepts minority views and rejects the majority, resulting in self-appreciation." },
  { domain: "Social & Cultural Diversity", question: "Familism in Hispanic culture refers to:", options: ["A) Preference for individual therapy", "B) Distrust of outsiders", "C) Fear of authority", "D) Strong identification with and attachment to family"], correct: 3, explanation: "Familism is a strong identification with and attachment to family, essential to understand when counseling Hispanic clients." },
  { domain: "Social & Cultural Diversity", question: "Cultural relativity means:", options: ["A) Only Western values are valid", "B) All behaviors are universally acceptable", "C) A behavior cannot be assessed as good or bad except within its cultural context", "D) Culture has no impact on behavior"], correct: 2, explanation: "Cultural relativity holds that a behavior cannot be assessed as good or bad except within the context of a given culture." },
  { domain: "Social & Cultural Diversity", question: "An 'autoplastic' worldview asserts:", options: ["A) Change comes from altering external factors", "B) Change is impossible", "C) Change requires medication", "D) Change comes from within the individual"], correct: 3, explanation: "Autoplastic = change from within. Alloplastic = change by altering external environmental factors." },
  { domain: "Social & Cultural Diversity", question: "Disproportionality in schools refers to:", options: ["A) Treating some students differently by disproportionate referrals to special ed or discipline", "B) Equal treatment of all students", "C) Having too many students per class", "D) Unequal funding between schools"], correct: 0, explanation: "Disproportionality is treating some school-age children differently, resulting in unneeded services, less rigorous curricula, and more disciplinary consequences." },
  { domain: "Social & Cultural Diversity", question: "Paralanguage includes:", options: ["A) Vocal cues like loudness, pauses, rate of speech, and inflection", "B) Body language only", "C) Sign language", "D) Written communication only"], correct: 0, explanation: "Paralanguage refers to vocal cues including loudness, pauses, silences, hesitations, rate of speech, and inflection." },
  { domain: "Social & Cultural Diversity", question: "ADA (1990) prohibits:", options: ["A) All testing", "B) Discrimination against the disabled by employers of 15+ workers", "C) Age discrimination only", "D) Immigration restrictions"], correct: 1, explanation: "The ADA prohibits employers of 15+ workers from discriminating against the disabled, and prohibits discrimination in transportation and access to public facilities." },
  { domain: "Social & Cultural Diversity", question: "IDEA (2004) requires:", options: ["A) Standardized testing for all", "B) Universal preschool", "C) Free appropriate public education for children ages 3-21 with disabilities", "D) Private school vouchers"], correct: 2, explanation: "IDEA requires free, appropriate public education for all children ages 3-21 with qualifying disabilities, in the least restrictive environment with an IEP." },
  { domain: "Human Growth & Development", question: "Erikson's 'Autonomy vs. Shame and Doubt' occurs during:", options: ["A) 1.5 to 3 years", "B) 3 to 6 years", "C) Birth to 1.5 years", "D) 6 to 11 years"], correct: 0, explanation: "Autonomy vs. Shame and Doubt occurs from 1.5 to 3 years. The infant asserts self and develops independence if allowed." },
  { domain: "Human Growth & Development", question: "Freud's anal stage involves:", options: ["A) Oral fixation", "B) Social interests replacing sexual interests", "C) Pleasure from expelling feces; issues of control", "D) The Oedipal complex"], correct: 2, explanation: "The anal stage (18 months-3 years) involves control issues. Anal retentive = obsessed with cleanliness; anal expulsive = unclean." },
  { domain: "Human Growth & Development", question: "Piaget's 'assimilation' refers to:", options: ["A) Creating new schemas", "B) Forgetting old info", "C) Modifying structures for new info", "D) Modifying environmental events to fit existing cognitive structures"], correct: 3, explanation: "Assimilation modifies environmental events to fit existing structures. Accommodation modifies structures for the environment." },
  { domain: "Human Growth & Development", question: "Thorndike's Law of Effect states:", options: ["A) Conditioning needs a neutral stimulus", "B) All behaviors are innate", "C) When a stimulus-response is followed by a reward, the connection is strengthened", "D) Punishment always eliminates behavior"], correct: 2, explanation: "The Law of Effect: a behavior's consequences determine the probability of it being repeated." },
  { domain: "Human Growth & Development", question: "Negative reinforcement involves:", options: ["A) Removing something distressing to increase behavior", "B) Taking away a toy", "C) Giving time-out", "D) Adding punishment"], correct: 0, explanation: "Negative reinforcement increases behavior by removing something distressing. It differs from punishment, which decreases behavior." },
  { domain: "Human Growth & Development", question: "A variable ratio schedule of reinforcement:", options: ["A) Is intermittent and elicits maximum desired behavior", "B) Uses fixed time intervals", "C) Reinforces every 5th behavior", "D) Produces the least desired behavior"], correct: 0, explanation: "Variable ratio is intermittent — the person doesn't know when reinforcement is coming. It elicits maximum behavior. Fixed interval (e.g., biweekly pay) elicits the least." },
  { domain: "Human Growth & Development", question: "Robert Havighurst's developmental tasks are:", options: ["A) Epigenetic — each requires completion of the last", "B) Culturally irrelevant", "C) Only for children", "D) Purely biological"], correct: 0, explanation: "Havighurst's stages are epigenetic — each requires completion of the last for success. Tasks arise from maturation, cultural influences, and personal values." },
  { domain: "Human Growth & Development", question: "Eleanor Gibson's visual cliff experiment showed:", options: ["A) Babies prefer bright colors", "B) Babies can't see at birth", "C) Vision is complete at 6 months", "D) Infants have depth perception and won't crawl across a perceived drop"], correct: 3, explanation: "Babies would not crawl across the visual cliff, demonstrating early depth perception." },
  { domain: "Career Development", question: "Holland's 'consistency' means:", options: ["A) Test reliability", "B) All six types are equal", "C) Work environments are stable", "D) Adjacent hexagon types are more psychologically alike"], correct: 3, explanation: "Adjacent pairs on the hexagon (e.g., Realistic-Investigative) are more psychologically alike than nonadjacent pairs." },
  { domain: "Career Development", question: "Gottfredson's 'Zone of Acceptable Alternatives':", options: ["A) Occupations consistent with the individual's self-concept", "B) Job market conditions", "C) A backup career list", "D) A geographic job search area"], correct: 0, explanation: "Individuals identify a Zone of Acceptable Alternatives — occupations within this range are consistent with their self-concept." },
  { domain: "Career Development", question: "The Occupational Outlook Handbook is published by:", options: ["A) CACREP", "B) The ACA", "C) US Department of Labor every 2 years", "D) Private publishers"], correct: 2, explanation: "Published every 2 years by the DOL, it contains job trends, employment projections, and salary data." },
  { domain: "Career Development", question: "The glass ceiling refers to:", options: ["A) Salary caps", "B) The highest office floor", "C) Invisible restraints limiting advancement up the career ladder", "D) A physical barrier"], correct: 2, explanation: "The glass ceiling is a set of invisible restraints typically imposed to limit ability to move up the career ladder." },
  { domain: "Career Development", question: "The CASVE cycle stands for:", options: ["A) Confidence, Awareness, Skills, Values, Education", "B) Choice, Action, Support, Verification, Evaluation", "C) Career, Assessment, Selection, Vocational, Employment", "D) Communication, Analysis, Synthesis, Valuing, Execution"], correct: 3, explanation: "CASVE is a sequential procedure for career problem-solving: Communication, Analysis, Synthesis, Valuing, Execution." },
  { domain: "Helping Relationships", question: "Whitaker's family therapy approach is:", options: ["A) Highly structured", "B) Experiential — less reliant on theory, therapist highly involved", "C) Psychoeducational", "D) Behavioral"], correct: 1, explanation: "Whitaker's experiential family therapy is less reliant on theory; the therapist becomes highly involved, challenging old patterns." },
  { domain: "Helping Relationships", question: "The empty chair technique is used in:", options: ["A) Gestalt therapy for addressing unfinished business", "B) Reality therapy", "C) CBT", "D) Psychoanalysis"], correct: 0, explanation: "The empty chair (Fritz Perls/Gestalt) helps clients address unfinished business by talking to an imagined person in an empty chair." },
  { domain: "Helping Relationships", question: "OARS in motivational interviewing stands for:", options: ["A) Open questions, Affirmations, Reflections, Summaries", "B) Outline, Address, Redirect, Solve", "C) Orient, Assess, Recommend, Support", "D) Observe, Analyze, Reflect, Summarize"], correct: 0, explanation: "OARS (Miller & Rollnick): Open questions, Affirmations, Reflections, Summaries." },
  { domain: "Helping Relationships", question: "A genogram is:", options: ["A) A personality test", "B) A family relationship diagram spanning 3+ generations", "C) A career tool", "D) A group technique"], correct: 1, explanation: "A genogram diagrams family relationships across at least three generations, used in Bowen's family systems therapy." },
  { domain: "Helping Relationships", question: "Homeostasis in family therapy is:", options: ["A) Physical health", "B) A dynamic state of equilibrium in the system", "C) Equal family power", "D) Financial stability"], correct: 1, explanation: "Homeostasis is the family system's dynamic equilibrium. Families resist change to maintain familiar patterns." },
  { domain: "Helping Relationships", question: "DBT by Linehan includes which four modules?", options: ["A) Sensing, intuiting, thinking, feeling", "B) Id, Ego, Superego, Unconscious", "C) Trust, autonomy, initiative, industry", "D) Distress tolerance, emotional regulation, interpersonal effectiveness, mindfulness"], correct: 3, explanation: "DBT: distress tolerance, emotional regulation, interpersonal effectiveness, mindfulness. Originally for borderline personality disorder." },
  { domain: "Group Counseling", question: "Goals of group counseling include all EXCEPT:", options: ["A) Eliminating all conflict", "B) Increasing self-direction", "C) Learning to trust self and others", "D) Learning effective social skills"], correct: 0, explanation: "Goals include trust, self-knowledge, conflict resolution skills, and social skills. Eliminating ALL conflict is not realistic." },
  { domain: "Group Counseling", question: "A guidance group focuses on:", options: ["A) Personality reconstruction", "B) Providing information and discussing its relevance", "C) Deep emotional processing", "D) Behavior modification"], correct: 1, explanation: "Guidance groups provide information and discuss its relevance. Often found in schools." },
  { domain: "Group Counseling", question: "Coalitions in family/group settings are:", options: ["A) Covert alliances between certain members against others", "B) Professional organizations", "C) Open alliances", "D) Therapeutic contracts"], correct: 0, explanation: "Coalitions are covert alliances (temporary or long-term) between certain members against others." },
  { domain: "Group Counseling", question: "Family sculpting involves:", options: ["A) Physical arrangement of family members in space to represent relationships", "B) Drawing portraits", "C) Writing narratives", "D) Art therapy with clay"], correct: 0, explanation: "Family sculpting physically arranges members in space to visually represent their relationships and dynamics." },
  { domain: "Assessment & Testing", question: "The MMPI is classified as:", options: ["A) An objective personality inventory", "B) A projective test", "C) An intelligence test", "D) A career interest inventory"], correct: 0, explanation: "The MMPI is an objective personality inventory using forced-choice items, contrasting with projective tests like the Rorschach." },
  { domain: "Assessment & Testing", question: "The TAT is:", options: ["A) A projective test where clients tell stories about ambiguous pictures", "B) An achievement test", "C) An IQ test", "D) A career test"], correct: 0, explanation: "The Thematic Apperception Test is projective — clients tell stories about ambiguous pictures, projecting their personality." },
  { domain: "Assessment & Testing", question: "The Standard Error of Measurement helps determine:", options: ["A) Test validity", "B) Test cost", "C) Item difficulty", "D) The range within which a true score probably falls"], correct: 3, explanation: "The SEM creates confidence bands showing the range within which an individual's true score probably falls." },
  { domain: "Assessment & Testing", question: "Sociometry can identify:", options: ["A) Career interests", "B) Personality disorders", "C) Isolates, rejectees, or stars within a social group", "D) Intelligence levels"], correct: 2, explanation: "Sociometry identifies isolates, rejectees, and stars. A sociogram is the visual map of group interrelationships." },
  { domain: "Assessment & Testing", question: "Convergent validity occurs when:", options: ["A) Items come from the correct domain", "B) There is no correlation", "C) The test predicts future behavior", "D) High correlation exists between the construct measured and related constructs"], correct: 3, explanation: "Convergent validity = high correlation with related constructs. Discriminant validity = no significant correlation with unrelated constructs." },
  { domain: "Assessment & Testing", question: "A spiral test arranges items:", options: ["A) Alphabetically", "B) By domain", "C) In progressively more difficult order", "D) Randomly"], correct: 2, explanation: "Spiral tests get progressively harder. Cyclical tests go easy-to-hard within each section." },
  { domain: "Research & Program Evaluation", question: "Inductive research:", options: ["A) Begins at the real-world level and leads to building theory", "B) Springs from theory", "C) Uses only quantitative methods", "D) Is always experimental"], correct: 0, explanation: "Inductive research begins practically and builds theory. Deductive research springs from established theory." },
  { domain: "Research & Program Evaluation", question: "A null hypothesis states:", options: ["A) There will be a significant difference", "B) The study has no purpose", "C) There is no difference between the groups measured", "D) One group will score higher"], correct: 2, explanation: "The null hypothesis states no difference. Researchers try to reject it to demonstrate significance." },
  { domain: "Research & Program Evaluation", question: "The independent variable is:", options: ["A) What you measure", "B) The control group", "C) What you manipulate to observe change in the dependent variable", "D) A confound"], correct: 2, explanation: "The IV is manipulated; the DV is measured/observed for changes." },
  { domain: "Research & Program Evaluation", question: "Demand characteristics are:", options: ["A) Sample size calculations", "B) Study requirements", "C) Statistical requirements", "D) Cues and knowledge subjects have about the experiment that influence performance"], correct: 3, explanation: "Demand characteristics include cues and knowledge the subject has about the experiment, threatening external validity." },
  { domain: "Research & Program Evaluation", question: "Post hoc tests are conducted when:", options: ["A) Sample is too small", "B) ANOVA shows significant F value and you need to find which groups differ", "C) Before the study", "D) Null hypothesis is accepted"], correct: 1, explanation: "Post hoc tests (Scheffé's, Tukey's HSD, etc.) determine which specific groups differ after a significant ANOVA result." },
  { domain: "Research & Program Evaluation", question: "Factor analysis:", options: ["A) Determines if variables can be reduced to fewer underlying factors", "B) Calculates effect size", "C) Tests normality", "D) Compares two group means"], correct: 0, explanation: "Factor analysis uses correlations to determine whether many variables can be reduced to a smaller number of underlying factors." },
  { domain: "Research & Program Evaluation", question: "Cross-sectional research:", options: ["A) Is always qualitative", "B) Uses one participant", "C) Collects data from different groups at the same time", "D) Follows the same group over time"], correct: 2, explanation: "Cross-sectional = different groups at same time. Longitudinal = same group over time." },
  { domain: "Research & Program Evaluation", question: "Ethnographic research involves:", options: ["A) Statistical hypothesis testing", "B) Describing and interpreting a cultural group through observation and interviewing", "C) Randomized trials", "D) Meta-analysis"], correct: 1, explanation: "Ethnography describes and interprets cultural/social groups via observation and interviewing; observer bias is a consideration." }
];

